@@ -1,6 +1,6 @@
 import { test } from "node:test";
 import assert from "node:assert/strict";
-import { addLine, createOrder, summary } from "../src/orders.js";
+import { addLine, createOrder, refund, summary } from "../src/orders.js";

 const mug = { price: 1200, quantity: 2 };
 const tee = { price: 2500, quantity: 1 };
@@ -22,6 +22,36 @@ test("a refunded order cannot change", () => {
   assert.throws(() => addLine(order, tee), /refunded order/);
 });

+test("an order can be partially and then fully refunded", () => {
+  const order = createOrder("o1", [mug]);
+  const partial = refund(order, 1000);
+
+  assert.deepEqual(
+    { refunded: partial.refunded, status: partial.status },
+    { refunded: 1000, status: "partially_refunded" },
+  );
+  assert.deepEqual(
+    { refunded: order.refunded, status: order.status },
+    { refunded: 0, status: "paid" },
+  );
+
+  const complete = refund(partial, 1400);
+  assert.deepEqual(
+    { refunded: complete.refunded, status: complete.status },
+    { refunded: 2400, status: "refunded" },
+  );
+});
+
+test("a refund amount must be positive and within the remaining balance", () => {
+  const order = createOrder("o1", [mug]);
+
+  assert.throws(() => refund(order, 0), RangeError);
+  assert.throws(() => refund(order, -1), RangeError);
+  assert.throws(() => refund(order, 2401), RangeError);
+  assert.throws(() => refund(order, Number.NaN), RangeError);
+  assert.throws(() => refund(refund(order, 1000), 1401), RangeError);
+});
+
 test("the summary counts items", () => {
   assert.equal(summary(createOrder("o1", [mug, tee])), "o1: 3 item(s), 4900 cents, paid");
 });

